// Apple's sample attestation object, quoted from the attestation object
// validation guide by appattest-swift PR #81, carries the iOS 27 authenticator
// extensions: its authenticator data is 226 bytes, 62 of them a trailing CBOR map.
// https://developer.apple.com/documentation/devicecheck/attestation-object-validation-guide
func TestParseAppleSampleAttestation(t *testing.T) {
	aar := AuthenticatorAttestationResponse{}
	if err := json.Unmarshal([]byte(appleSampleAttestation), &aar); err != nil {
		t.Fatal(err)
	}

	a, err := aar.parse()
	if err != nil {
		t.Fatalf("parse: %v", err)
	}

	if a.Format != attestationKey {
		t.Errorf("format = %q, want %q", a.Format, attestationKey)
	}
	if len(a.RawAuthData) != 226 {
		t.Errorf("authenticator data length = %d, want 226", len(a.RawAuthData))
	}
	if got := string(a.AuthData.AttData.AAGUID); got != "appattest\x00\x00\x00\x00\x00\x00\x00" {
		t.Errorf("AAGUID = %q, want the production AAGUID", got)
	}

	ext := a.AuthData.Extensions
	if ext == nil {
		t.Fatal("extensions were not parsed")
	}
	if ext.ValidationCategory == nil {
		t.Fatal("validation category was not parsed")
	}
	if *ext.ValidationCategory != authenticator.ValidationCategoryPlatform {
		t.Errorf("validation category = %v, want %v", *ext.ValidationCategory, authenticator.ValidationCategoryPlatform)
	}
}

// The extension bytes are covered by the attestation nonce, so they have to stay
// in the authenticator data rather than being stripped off as trailing junk.
// Reaching the nonce in the sample's credCert requires all 226 bytes.
func TestAppleSampleNonceCoversTheExtensionBytes(t *testing.T) {
	aar := AuthenticatorAttestationResponse{}
	if err := json.Unmarshal([]byte(appleSampleAttestation), &aar); err != nil {
		t.Fatal(err)
	}
	a, err := aar.parse()
	if err != nil {
		t.Fatalf("parse: %v", err)
	}

	// Apple's guide composes the nonce from the authenticator data and the raw
	// challenge, not its hash. See TestParseAppleSampleAttestation.
	composite := make([]byte, 0, len(a.RawAuthData)+len(appleSampleChallenge))
	composite = append(composite, a.RawAuthData...)
	composite = append(composite, appleSampleChallenge...)
	nonce := sha256.Sum256(composite)

	want, err := base64.StdEncoding.DecodeString(appleSampleNonce)
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(nonce[:], want) {
		t.Errorf("nonce = %s, want %s",
			base64.StdEncoding.EncodeToString(nonce[:]), appleSampleNonce)
	}
}

const (
	appleSampleChallenge = "example_server_challenge"
	// Read from the sample's credCert, OID 1.2.840.113635.100.8.2.
	appleSampleNonce = "h7fQbZOkKU5G8BHma2zEAPC6sgcpl2xhlYC0KuYL/24="
)
